/**
 * Collects the failures of release steps that must all run, so that one failing step does not keep the next one from releasing its thread-local state or listeners. rethrowFirst rethrows the first failure, with the later ones added to it as suppressed.  
 */
public final class CleanupFailures {
  private Throwable first;

  public CleanupFailures() {
  }

  /**
   * Runs the step and keeps its failure, an Error included, instead of throwing it.  
   */
  public void run(Runnable step) {
    try {
      step.run();
    } catch (Throwable e) {
      if (first == null) {
        first = e;
      } else if (first != e) {
        first.addSuppressed(e);
      }
    }
  }

  /**
   * Rethrows the first failure kept by run, if any, with the later ones as suppressed.  
   */
  public void rethrowFirst() {
    if (first instanceof RuntimeException) {
      throw (RuntimeException) first;
    }
    if (first instanceof Error) {
      throw (Error) first;
    }
    if (first != null) {
      throw new RuntimeException(first);
    }
  }
}
